+void _gracefulHeadlessExit(
+  void Function() fireInterrupt, {
+  String signal = 'SIGINT',
+}) {
+  if (signal != 'SIGINT') {
+    stderr.writeln(
+      'fa: $signal received — aborting headless run gracefully '
+      '(exit 130; a second $signal forces exit 143)',
+    );
+  }
   fireInterrupt();
